grid = [list(map(int, line.split())) for line in grid_data.strip().split('\n')]

print(f"Grid shape: {len(grid)} x {len(grid[0])}")

horizontal_lines = [i for i, row in enumerate(grid) if all(x == 2 for x in row)]
vertical_lines = [j for j in range(len(grid[0])) if all(grid[i][j] == 2 for i in range(len(grid)))]

print(f"Horizontal lines: rows {horizontal_lines}")
print(f"Vertical lines: columns {vertical_lines}")

# Count 8s position in each region
horizontal_regions = []
start = 0
end = len(grid)
for line in horizontal_lines:
    horizontal_regions.append((start, line))
    start = line + 1
horizontal_regions.append((start, end))

vertical_regions = []
start = 0
end = len(grid[0])
for line in vertical_lines:
    vertical_regions.append((start, line))
    start = line + 1
vertical_regions.append((start, end))

print(f"Horizontal regions: {horizontal_regions}")
print(f"Vertical regions: {vertical_regions}")

region_8s = {}
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] == 8:
            h_idx = None
            for i, (s, e) in enumerate(horizontal_regions):
                if s <= r < e:
                    h_idx = i
                    break
            v_idx = None
            for i, (s, e) in enumerate(vertical_regions):
                if s <= c < e:
                    v_idx = i
                    break
            if h_idx is not None and v_idx is not None:
                region_8s[(h_idx, v_idx)] = region_8s.get((h_idx, v_idx), 0) + 1

print(f"8s per region: {region_8s}")

# Visualize
def visualize():
    res = [['.' for _ in range(11)] for _ in range(19)]
    for r in horizontal_lines:
        for c in range(11):
            res[r][c] = '-'
    for c in vertical_lines:
        for r in range(19):
            res[r][c] = '|'
    for r in range(19):
        for c in range(11):
            if grid[r][c] == 8:
                res[r][c] = '8'
            elif grid[r][c] == 0:
                res[r][c] = ' '
    for row in res:
        print(''.join(row))

visualize()
